 document.addEventListener('DOMContentLoaded', () => {
     const form = document.getElementById('contact-form');
     const statusDiv = document.getElementById('form-status');

     const validators = {
         'full-name': (value) => {
             if (!value.trim()) return 'Please enter your full name.';
             return null;
         },
         'email': (value) => {
             if (!value.trim()) return 'Please enter your email address.';
             const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
             if (!emailRegex.test(value)) return 'Please enter a valid email address (e.g., name@example.com).';
             return null;
         },
         'phone': (value) => {
             if (!value.trim()) return null; // Optional
             const phoneRegex = /^\d{3}-\d{3}-\d{4}$/;
             if (!phoneRegex.test(value)) return 'Please enter a valid phone number (e.g., 123-456-7890).';
             return null;
         }
     };

     const validateField = (input) => {
         const errorId = input.getAttribute('aria-describedby').split(' ').find(id => id.endsWith('-error'));
         const errorElement = document.getElementById(errorId);
         const validator = validators[input.id];

         const errorMessage = validator ? validator(input.value) : null;

         if (errorMessage) {
             input.setAttribute('aria-invalid', 'true');
             errorElement.textContent = `Error: ${errorMessage}`;
             errorElement.hidden = false;
             return false;
         } else {
             input.removeAttribute('aria-invalid');
             errorElement.hidden = true;
             return true;
         }
     };

     // Validate on blur for better UX
     form.querySelectorAll('input').forEach(input => {
         input.addEventListener('blur', () => {
             validateField(input);
         });
     });

     form.addEventListener('submit', (event) => {
         event.preventDefault();

         const inputs = form.querySelectorAll('input');
         let firstInvalidField = null;
         let isFormValid = true;

         inputs.forEach(input => {
             const isValid = validateField(input);
             if (!isValid) {
                 isFormValid = false;
                 if (!firstInvalidField) {
                     firstInvalidField = input;
                 }
             }
         });

         if (!isFormValid) {
             firstInvalidField.focus();
             statusDiv.textContent = 'Submission failed. Please correct the errors above and try again.';
             statusDiv.className = 'form-status error';
