<body>
    <header>
        <h1>Support Page</h1>
    </header>
    <main>
        <section class="contact-form-section">
            <h2>Contact Us</h2>
            <p>Please fill out the form below and we'll get back to you as soon as possible. Fields marked with an asterisk (*) are required.</p>

            <form id="contact-form" novalidate>
                <div class="form-field">
                    <label for="full-name">Full Name <span aria-hidden="true">*</span></label>
                    <input 
                        id="full-name" 
                        name="full-name" 
                        type="text" 
                        required 
                        autocomplete="name"
                        aria-describedby="name-error"
                    >
                    <p id="name-error" class="error-message" hidden aria-live="assertive"></p>
                </div>

                <div class="form-field">
                    <label for="email">Email Address <span aria-hidden="true">*</span></label>
                    <input 
                        id="email" 
                        name="email" 
                        type="email" 
                        required 
                        autocomplete="email"
                        aria-describedby="email-error"
                    >
                    <p id="email-error" class="error-message" hidden aria-live="assertive"></p>
                </div>

                <div class="form-field">
                    <label for="phone">Phone Number (optional)</label>
                    <p id="phone-help" class="help-text">Format: 123-456-7890</p>
                    <input 
                        id="phone" 
                        name="phone" 
                        type="tel" 
                        autocomplete="tel"
                        aria-describedby="phone-help phone-error"
                    >
                    <p id="phone-error" class="error-message" hidden aria-live="assertive"></p>
                </div>

                <div class="form-actions">
                    <button type="submit">Send Message</button>
                </div>

                <div id="form-status" aria-live="polite" class="form-status"></div>
            </form>
        </section>
    </main>
    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const form = document.getElementById('contact-form');
            const statusDiv = document.getElementById('form-status');

            const validators = {
                'full-name': (value) => {
                    if (!value.trim()) return 'Please enter your full name.';
                    return null;
                },
                'email': (value) => {
                    if (!value.trim()) return 'Please enter your email address.';
                    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                    if (!emailRegex.test(value)) return 'Please enter a valid email address (e.g., name@example.com).';
                    return null;
                },
                'phone': (value) => {
                    if (!value.trim()) return null; // Optional
                    const phoneRegex = /^\d{3}-\d{3}-\d{4}$/;
                    if (!phoneRegex.test(value)) return 'Please enter a valid phone number (e.g., 123-456-7890).';
                    return null;
                }
            };

            const validateField = (input) => {
                const errorId = input.getAttribute('aria-describedby').split(' ').find(id => id.endsWith('-error'));
                const errorElement = document.getElementById(errorId);
                const validator = validators[input.id];

                const errorMessage = validator ? validator(input.value) : null;

                if (errorMessage) {
                    input.setAttribute('aria-invalid', 'true');
                    errorElement.textContent = `Error: ${errorMessage}`;
                    errorElement.hidden = false;
                    return false;
                } else {
                    input.removeAttribute('aria-invalid');
                    errorElement.textContent = '';
                    errorElement.hidden = true;
                    return true;
                }
            };

            // Validate on blur for better UX
            form.querySelectorAll('input').forEach(input => {
                input.addEventListener('blur', () => {
                    validateField(input);
                });
            });

            form.addEventListener('submit', (event) => {
                event.preventDefault();

                const inputs = form.querySelectorAll('input');
                let firstInvalidField = null;
                let isFormValid = true;

                inputs.forEach(input => {
                    const isValid = validateField(input);
                    if (!isValid) {
                        isFormValid = false;
                        if (!firstInvalidField) {
                            firstInvalidField = input;
                        }
                    }
                });

                if (!isFormValid) {
                    firstInvalidField.focus();
                    statusDiv.textContent = 'Submission failed. Please correct the errors above and try again.';
                    statusDiv.className = 'form-status error';
                } else {
                    // Simulate successful submission
                    statusDiv.textContent = 'Thank you! Your message has been sent successfully.';
                    statusDiv.className = 'form-status success';
                    form.reset();
                    // Clear any lingering aria-invalid states
                    inputs.forEach(input => {
                        input.removeAttribute('aria-invalid');
                        const errorId = input.getAttribute('aria-describedby').split(' ').find(id => id.endsWith('-error'));
                        const err = document.getElementById(errorId);
                        err.hidden = true;
                        err.textContent = '';
                    });
                }
            });
        });
    </script>
</body>
</html>
